const customers = $input.all().map(i => i.json);
const now = new Date();

// Enrich each customer with churn signals
return customers.map(c => {
  const props = c.properties || c;
  const lastActivity = props.hs_last_sales_activity_date ? new Date(props.hs_last_sales_activity_date) : null;
  const daysSinceActivity = lastActivity ? Math.floor((now - lastActivity) / 86400000) : 999;
  const closeDate = props.closedate ? new Date(props.closedate) : null;
  const daysToRenewal = closeDate ? Math.floor((closeDate - now) / 86400000) : 999;
  const pageViews = parseInt(props.hs_analytics_num_visits || '0', 10);

  return { json: {
    customer_id: c.id || props.hs_object_id,
    name: `${props.firstname || ''} ${props.lastname || ''}`.trim() || 'Unknown',
    email: props.email || '',
    company: props.company || 'Unknown',
    days_since_activity: daysSinceActivity,
    days_to_renewal: daysToRenewal,
    page_views: pageViews,
    support_tickets: parseInt(props.num_notes || '0', 10),
    renewal_soon: daysToRenewal <= 30 && daysToRenewal > 0
  }};
}).map(i => i);

