const raw = $input.item.json.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch(e) {
  parsed = { churn_score: 50, reason: 'Unable to parse', action: 'Manual review needed' };
}

const customer = $('Enrich with Churn Signals').item.json;

return [{ json: {
  ...customer,
  churn_score: parsed.churn_score || 50,
  churn_reason: parsed.reason || '',
  recommended_action: parsed.action || '',
  is_high_risk: (parsed.churn_score || 50) >= $('Config').item.json.CHURN_RISK_THRESHOLD
}}];

// Aggregate all high-risk customers and post summary to Slack
const atRisk = $input.all().map(i => i.json);
atRisk.sort((a, b) => b.churn_score - a.churn_score);

if (atRisk.length === 0) {
  return [{ json: { slack_message: 'No high-risk customers this week. All accounts look healthy.', count: 0 } }];
}

const lines = atRisk.slice(0, 10).map((c, i) => 
  `${i+1}. *${c.company}* (${c.name}) — Risk: ${c.churn_score}/100${c.renewal_soon ? ' :warning: Renewal soon' : ''}\n   Reason: ${c.churn_reason}\n   Action: ${c.recommended_action}`
).join('\n\n');

return [{ json: {
  slack_message: lines,
  count: atRisk.length,
  top_risk: atRisk[0]?.company || 'N/A'
}}];

